/**
 * Retirements made after this instant are still held. The hold ends at
 * exactly `ORG_SLUG_HOLD_DAYS` days, so a row retired *at* the cutoff is
 * already released.
 */
function slugHoldCutoff(now: Date = new Date()): string {
  return toIsoTimestamp(new Date(now.getTime() - ORG_SLUG_HOLD_DAYS * MS_PER_DAY));
}

/**
 * The one rule for turning a slug into a workspace (ADR 0005): the workspace
 * whose current slug it is, otherwise the workspace that retired it within
 * the hold window. Archived workspaces never resolve.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const db = getDb();

  const current = db
    .select()
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  if (current) {
    return current.archivedAt === null ? toOrganization(current) : null;
  }

  const held = db
    .select({ org: organizations })
    .from(organizationRetiredSlugs)
    .innerJoin(
      organizations,
      eq(organizations.id, organizationRetiredSlugs.orgId),
    )
    .where(
      and(
        eq(organizationRetiredSlugs.slug, slug),
        gt(organizationRetiredSlugs.retiredAt, slugHoldCutoff()),
        isNull(organizations.archivedAt),
      ),
    )
    .get();

  return held ? toOrganization(held.org) : null;
}

/**
 * Whether `orgId` may take `slug` by rename: no other workspace (live or
 * deleted) has it as its current slug, and no other workspace holds it
 * retired. The workspace's own retired slugs are always available to it.
 */
export async function isOrgSlugAvailableFor(
  orgId: OrgId,
  slug: string,
): Promise<boolean> {
  const db = getDb();

  const current = db
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (current) return false;

  const held = db
    .select({ id: organizationRetiredSlugs.id })
    .from(organizationRetiredSlugs)
    .where(
      and(
        eq(organizationRetiredSlugs.slug, slug),
        ne(organizationRetiredSlugs.orgId, orgId),
        gt(organizationRetiredSlugs.retiredAt, slugHoldCutoff()),
      ),
    )
    .get();

  return !held;
}

/**
 * Writes the new current slug and retires the one it replaces, atomically.
 * Any retirement of the new slug that is the workspace's own, or that has
 * lapsed, is cleared. Availability is the caller's check; only the slug and
 * `updatedAt` are written.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<Organization> {
  const now = new Date();
  const stamp = toIsoTimestamp(now);

  const row = getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);
    if (current.slug === slug) return current;

    tx.delete(organizationRetiredSlugs)
      .where(
        and(
          eq(organizationRetiredSlugs.slug, slug),
          or(
            eq(organizationRetiredSlugs.orgId, orgId),
            lte(organizationRetiredSlugs.retiredAt, slugHoldCutoff(now)),
          ),
        ),
      )
      .run();

    tx.delete(organizationRetiredSlugs)
      .where(
        and(
          eq(organizationRetiredSlugs.orgId, orgId),
          eq(organizationRetiredSlugs.slug, current.slug),
        ),
      )
      .run();
    tx.insert(organizationRetiredSlugs)
      .values({
        id: newId(),
        orgId,
        slug: current.slug,
        retiredAt: stamp,
      })
      .run();

    return tx
      .update(organizations)
      .set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();
  });

  return toOrganization(row);
}''')
