 * released: it keeps resolving here for `ORG_SLUG_HOLD_DAYS` days.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const from = org.slug;
  const to = input.slug;
  if (to === from) return org;

  assertValidSlug(to);
  if (!(await orgRepo.isOrgSlugAvailableFor(org.id, to))) {
    throw new InvalidSlugError(to, "is not available");
  }

  const updated = await orgRepo.renameOrgSlug(org.id, to);

  await record(org.id, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: org.id,
    projectId: null,
    summary: `Workspace URL changed from ${from} to ${to}`,
    metadata: { from, to },
  });

  await emit("organization.slug_changed", {
    ...actorEnvelope({ ...actor, orgId: org.id }),
    from,
    to,
  });

  return updated;
}

