export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const db = getDb();
  const current = db
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  const held = db
    .select({ slug: organizationRetiredSlugs.slug })
    .from(organizationRetiredSlugs)
    .where(
      and(
        like(organizationRetiredSlugs.slug, `${prefix}%`),
        gt(organizationRetiredSlugs.retiredAt, slugHoldCutoff()),
      ),
    )
    .all();
