/**
 * Renaming a workspace's slug (ADR 0005): refusal instead of suffixing, the
 * retired slug's hold, chains, and the single event / audit row.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { InvalidSlugError } from "@/lib/slug";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as orgService from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { IsoTimestamp } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

const DAY = 24 * 60 * 60 * 1000;
const HOLD = ORG_SLUG_HOLD_DAYS * DAY;

let cleanup: () => void;
let a: Tenant;
let b: Tenant;
const detachers: Unsubscribe[] = [];

function capture(): TaskflowEventMap["organization.slug_changed"][] {
  const seen: TaskflowEventMap["organization.slug_changed"][] = [];
  detachers.push(subscribe("organization.slug_changed", (p) => void seen.push(p)));
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  a = await createTenant("alpha");
  b = await createTenant("beta");
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => cleanup());

describe("renameOrganizationSlug", () => {
  it("refuses viewers/members, bad slugs and taken slugs without changing anything", async () => {
    const seen = capture();
    await expect(
      orgService.renameOrganizationSlug(a.actors.member, { orgId: a.org.id, slug: "nope" }),
    ).rejects.toThrow();
    await expect(
      orgService.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "settings" }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(
      orgService.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "Bad Slug" }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(
      orgService.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "beta" }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(
      orgService.renameOrganizationSlug(b.actors.admin, { orgId: a.org.id, slug: "nope" }),
    ).rejects.toThrow();

    expect(seen).toHaveLength(0);
    expect((await orgRepo.findOrgById(a.org.id))?.slug).toBe("alpha");
    expect(await orgRepo.findOrgBySlug("nope")).toBeNull();
  });

  it("is a no-op for the current slug", async () => {
    const seen = capture();
    const result = await orgService.renameOrganizationSlug(a.actors.admin, {
      orgId: a.org.id,
      slug: "alpha",
    });
    expect(result).toEqual(await orgRepo.findOrgById(a.org.id));
    expect(seen).toHaveLength(0);
  });

  it("renames, announces once, and holds the old slug for exactly the hold", async () => {
    const start = Date.now();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(start);
    const seen = capture();

    const renamed = await orgService.renameOrganizationSlug(a.actors.admin, {
      orgId: a.org.id,
      slug: "alpha-two",
    });

    expect(renamed.slug).toBe("alpha-two");
    expect(renamed.name).toBe(a.org.name);
    expect(renamed.settings).toEqual(a.org.settings);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: a.org.id,
      actorId: a.userIds.admin,
      from: "alpha",
      to: "alpha-two",
    });

    const audit = await activityRepo.listActivity({
      orgId: a.org.id,
      action: ["organization.slug_changed"],
      limit: 10,
      cursor: null,
    } as never);
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      subjectKind: "organization",
      subjectId: a.org.id,
      actorId: a.userIds.admin,
      metadata: { from: "alpha", to: "alpha-two" },
    });

    const summary = await orgService.getOrganizationSummary(a.actors.owner, a.org.id);
    expect(summary.organization.slug).toBe("alpha-two");
    const listed = await orgService.listOrganizationsForUser(a.userIds.owner);
    expect(listed.map((org) => org.slug)).toEqual(["alpha-two"]);

    // Both slugs resolve, through the service and the session layer.
    const principal = {
      userId: a.userIds.member,
      email: "member@alpha.test",
      activeOrgId: null,
      expiresAt: new Date(start + DAY).toISOString() as IsoTimestamp,
    };
    expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);
    expect((await orgService.resolveOrgBySlug("alpha-two"))?.id).toBe(a.org.id);
    expect((await resolveActorForOrg(principal, "alpha"))?.orgId).toBe(a.org.id);

    // Nobody else can take it; creation suffixes around it.
    await expect(
      orgService.renameOrganizationSlug(b.actors.admin, { orgId: b.org.id, slug: "alpha" }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
    const created = await orgService.createOrganization(b.userIds.owner, {
      name: "Alpha",
      slug: "alpha",
      plan: "free",
    });
    expect(created.slug).toBe("alpha-2");

    vi.setSystemTime(start + HOLD - 1);
    expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);

    vi.setSystemTime(start + HOLD);
    expect(await orgService.resolveOrgBySlug("alpha")).toBeNull();
    expect(await resolveActorForOrg(principal, "alpha")).toBeNull();

    const taken = await orgService.renameOrganizationSlug(b.actors.admin, {
      orgId: b.org.id,
      slug: "alpha",
    });
    expect(taken.slug).toBe("alpha");
    expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(b.org.id);
    // b's old slug is now held for b.
    expect((await orgService.resolveOrgBySlug("beta"))?.id).toBe(b.org.id);
  });

  it("renaming back ends the retirement and retires the replaced slug", async () => {
    const start = Date.now();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(start);

    await orgService.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "beta" });
    expect((await orgRepo.findOrgById(b.org.id))?.slug).toBe("beta");
    expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(b.org.id);

    vi.setSystemTime(start + HOLD + DAY);
    expect((await orgService.resolveOrgBySlug("beta"))?.id).toBe(b.org.id);
    expect(await orgService.resolveOrgBySlug("alpha")).toBeNull();
  });
});
